# -*- coding: utf-8 -*-
"""OA-size scenario stories, batch 10: bits, linked lists, trees, first trie variant. 250+ words each."""

QUESTIONS = [

{"id": "sc-140", "v": "bt-subsets", "dom": "museum curation", "diff": "M",
 "title": "The Jury of the Calloway Collection",
 "story": "The Calloway Museum has inherited a bequest of exhibits, each one a curious object collected by a Victorian physician, and the board of trustees must now decide which of them to display in the new east wing. The collection is small, as these things go: only N objects, N being at most eighteen, and each object has been assigned a weight of cultural significance by the curator, a whole number which may be positive or negative, a negative figure signifying that the object is, in the curator's opinion, an embarrassment that detracts from the others.\n\nThe trustees will choose a selection of objects, any number of them from none to all, and the significance of a selection is the total of the weights of the objects in it. The east wing has a peculiar architectural feature that can be set up only for an exact total: a plaque specifying a target significance T, which must be met precisely. The trustees want to know how many different selections of objects have a combined significance of exactly T. Two selections are different if they differ in at least one object, even if their totals are the same, and the empty selection counts as a valid selection if its total, which is zero, equals T.\n\nThe physician's collection includes a stuffed armadillo, a set of glass eyes, a tin bath, and an alarming quantity of bottled medical specimens. The museum cafe has been criticised for its prices. The chair of the trustees, a lady of formidable bearing, has a habit of tapping her cane during debates.\n\nThe curator, a precise man named Lancelot Pyke, has pointed out that with so few objects one can afford to look at every possible selection once, and that this is the sensible thing to do, provided that each selection is considered only once and the total is computed without any needless repetition of work.\n\nInput: line one gives N and T. Line two gives the N weights. Output: the number of selections whose total is exactly T.\n\nConstraints: N up to 18; weights between -10^6 and 10^6; T between -10^8 and 10^8. The answer fits comfortably in a 64-bit integer. The number of objects is deliberately tiny so that the number of all possible selections, two multiplied by itself N times, is manageable.",
 "clues": ["only N objects, N being at most eighteen", "any number of them from none to all", "Two selections are different if they differ in at least one object", "the number of all possible selections, two multiplied by itself N times, is manageable"],
 "decoys": ["a stuffed armadillo, a set of glass eyes, a tin bath", "The museum cafe has been criticised for its prices"],
 "core": "With very few items, look at every possible selection of them and count those with a given total.",
 "gloss": [("bequest", "property left to someone in a will", True), ("trustees", "people who manage something for others", True), ("significance", "importance", True), ("detracts", "takes away from", True), ("physician", "a doctor", True)],
 "why": {"bk-subsets": "Generating subsets with a recursive search finds them too; the tight bound on N and the 'every selection once' wording point at counting through all binary patterns.", "dp-knapsack": "A subset-sum table is possible for small weights, but here weights can be negative and huge, and N is tiny."},
 "alt": ["bk-subsets"],
 "tell": "A tiny number of items and every selection to be checked: each selection is one binary pattern of in/out choices."},

{"id": "sc-141", "v": "bt-dp", "dom": "regatta", "diff": "H",
 "title": "The Crew List of the Henley Eights",
 "story": "The rowing club at Marlow is preparing its eight for the summer regatta, and the coach, a tireless woman named Philomena Ashby, has spent the winter measuring her squad of rowers. There are exactly N rowers and exactly N seats in the boat, N being at most sixteen, and every rower must be given exactly one seat, every seat taken by exactly one rower. A rower's suitability for a seat depends on the seat: the stroke seat needs rhythm, the bow seat needs balance, and the engine-room seats need raw power. Philomena has tested every rower in every seat and written down a cost for each pairing, a whole number representing how far that rower falls short of the ideal for that seat. Lower is better.\n\nPhilomena wishes to assign rowers to seats so that the total cost over the whole boat is as small as possible. It is not enough to give each seat to the rower with the lowest cost for it, because the same rower may be the best for several seats and cannot sit in more than one. And she cannot simply try every possible assignment: with sixteen rowers the number of ways to line them up is more than twenty trillion, and she has only an hour on the pontoon before the tide turns.\n\nThe club's boathouse smells of varnish and wet wool, and the veteran rowers tell stories of the great regatta of 1952, when a swan blocked the course. The cox, a diminutive boy named Fergus, has a surprisingly deep voice. The regatta's patron, a duke, is expected to attend, and the committee is nervous about the hospitality tent.\n\nPhilomena has noticed that the best way to assign the first few seats depends only on WHICH rowers have already been placed, not on the order in which they were placed. That observation seems important, but she cannot yet see how to use it.\n\nInput: line one gives N. The next N lines each give N costs: row i, column j is the cost of rower i in seat j. Output: the minimum possible total cost of a full assignment.\n\nConstraints: N up to 16; costs up to 10^6. The answer fits in 32 bits.",
 "clues": ["N being at most sixteen", "every rower must be given exactly one seat, every seat taken by exactly one rower", "the same rower may be the best for several seats and cannot sit in more than one", "depends only on WHICH rowers have already been placed, not on the order in which they were placed"],
 "decoys": ["the great regatta of 1952, when a swan blocked the course", "The cox, a diminutive boy named Fergus, has a surprisingly deep voice"],
 "core": "Assign each of N (at most 16) workers to a different task at minimum total cost; the state is which workers are already used.",
 "gloss": [("regatta", "a series of boat races", True), ("pontoon", "a floating platform", True), ("cox", "the person who steers a rowing boat", True), ("suitability", "how well something fits a purpose", True), ("diminutive", "very small", True)],
 "why": {"bk-perms": "Trying all orderings is correct but takes factorial time; the remark about the state being only 'which rowers are placed' invites reuse of work.", "gr-pair": "Pairing best with best fails when the same rower is the best for several seats."},
 "alt": [],
 "tell": "Tiny N, each item used exactly once, and the future depends only on which items are used so far: remember the best cost for every set of used items."},

{"id": "sc-142", "v": "bt-tricks", "dom": "organ building", "diff": "M",
 "title": "The Stop Registrations of the Great Organ",
 "story": "The Great Organ of Saint Hilda's has 30 stops, which are the knobs the organist draws out to select a family of pipes, and each stop is either drawn or pushed in. A particular arrangement of the stops is called a registration, and the church's librarian, a meticulous woman named Dorothea Quint, records each registration as a single whole number: the number is written in binary, the lowest digit standing for the first stop, the next for the second, and so on, with a digit of one meaning the stop is drawn and a digit of zero meaning it is pushed in.\n\nThe organist, Mr Ambrose Tilling, is composing a sequence of M pieces, and between each consecutive pair of pieces he must change the registration. Changing a stop takes him one second, for he has to reach over and pull or push it, and he can change only one stop at a time. He wants to know, for each consecutive pair of registrations, how many stops differ between the two, since that is the number of seconds he will spend between those two pieces; and in particular, how many seconds the whole performance will spend on changes.\n\nThe librarian also has a second question. For a handful of registrations, she wants to know whether exactly one stop is drawn, because such a registration is considered a 'solo voice' by the choir, and she keeps a separate shelf for them.\n\nThe church roof is leaking above the north transept, and a bucket sits in the aisle. The Reverend Hallam preaches long sermons about humility. The choir's tenors are rumoured to be on strike over the quality of the biscuits provided at rehearsals.\n\nInput: line one gives M. Line two gives M registrations (whole numbers below 2^30). Output: on the first line, the total number of stop changes between consecutive registrations; on the second line, the number of registrations in which exactly one stop is drawn.\n\nConstraints: M up to 10^6. Mr Tilling's laptop is old and slow, so Dorothea wants each registration to be handled in a handful of machine operations; she refuses to convert numbers to text strings of digits and count characters, and she has been told that there is a way to flip, test and count the individual digits of a number directly.",
 "clues": ["the number is written in binary, the lowest digit standing for the first stop", "how many stops differ between the two", "exactly one stop is drawn", "a way to flip, test and count the individual digits of a number directly"],
 "decoys": ["The church roof is leaking above the north transept", "The choir's tenors are rumoured to be on strike over the quality of the biscuits"],
 "core": "Count how many binary digits differ between two numbers, and test whether a number is a power of two, using direct digit operations.",
 "gloss": [("registration", "a chosen combination of organ stops", True), ("transept", "the arm of a cross-shaped church", True), ("meticulous", "very careful about detail", True), ("binary", "a number written with only zeros and ones", True), ("humility", "modesty", True)],
 "why": {"bt-xor": "Combining numbers to find differences is part of it, but the questions are about counting differing digits and spotting a single drawn stop, which need digit tricks beyond cancelling.", "bt-subsets": "No selection of subsets is enumerated."},
 "alt": [],
 "tell": "Per-number questions about individual binary digits: differing digits via combine-then-count, single digit set via a clear-lowest-digit test."},

{"id": "sc-143", "v": "ll-fastslow", "dom": "pilgrim routes", "diff": "M",
 "title": "The Hostels on the Road to Santiago",
 "story": "The old pilgrim road winds through the hills of northern Spain, and at intervals along it stand hostels where tired pilgrims can sleep. Each hostel keeps a register recording the name of the NEXT hostel on the road, to which a pilgrim should walk the following day; the last hostel in the chain, the one at the cathedral, records no next hostel at all. In this way the entire road is described by hostel after hostel, each pointing to the next. A cleric, Brother Anselmo, who has charge of the diocesan archive, has been given a newly discovered set of registers by a parish in the high sierra and is anxious to see whether they describe a proper road.\n\nHe suspects a mischief. A forger, or a muddled clerk, may have written the registers so that some hostel names, as its next stop, a hostel that was already visited earlier in the chain. In that case a pilgrim following the registers would walk in a circle forever and never reach the cathedral. Brother Anselmo has one pilgrim, a scrupulous young man named Tomas, and a handful of coloured pebbles, but he is not permitted to mark the hostels themselves, nor to keep a written list of hostels visited, because the archive is short of paper and the registers are fragile. Tomas must walk the road using only his own two legs and his wits.\n\nBrother Anselmo has two questions. First, does the road ever reach the cathedral, or does it loop? Second, if it does reach the cathedral, which hostel stands exactly in the middle of the road (in the case of an even number of hostels, the later of the two middle ones)?\n\nThe pilgrims of the region are partial to a thick soup made with chestnuts. A shop in the town of Burgos sells shells for hanging round the neck. The weather in the sierra is capricious.\n\nInput: line one gives N, the number of hostels. Line two gives, for each hostel numbered 1 to N, the number of its next hostel, or 0 if none. Hostel 1 is the start. Output: LOOP if the road never reaches the cathedral; otherwise the number of the middle hostel.\n\nConstraints: N up to 10^6. Memory used must not grow with N.",
 "clues": ["each pointing to the next", "a pilgrim following the registers would walk in a circle forever", "not permitted to mark the hostels themselves, nor to keep a written list of hostels visited", "Memory used must not grow with N"],
 "decoys": ["The pilgrims of the region are partial to a thick soup made with chestnuts", "A shop in the town of Burgos sells shells for hanging round the neck"],
 "core": "In a chain where each node names its successor, detect whether it loops and find the middle node, without marking nodes or using extra memory.",
 "gloss": [("diocesan", "belonging to a bishop's district", True), ("scrupulous", "very careful and honest", True), ("sierra", "a mountain range", True), ("capricious", "changing unpredictably", True), ("forger", "someone who makes fakes", True)],
 "why": {"hs-seen": "Remembering visited hostels would detect a loop, but the story forbids lists and marks.", "ll-reverse": "Rewiring the registers is forbidden, since they are fragile."},
 "alt": [],
 "tell": "A chain with possible loops and no extra memory: send two walkers at different speeds; they meet if there is a loop, and the slower is at the middle when the faster ends."},

{"id": "sc-144", "v": "ll-reverse", "dom": "barge towing", "diff": "H",
 "title": "The Barge Train of the Kennet Navigation",
 "story": "On the Kennet Navigation, a canal that threads the water-meadows of Berkshire, cargo is carried in trains of narrowboats coupled together one behind the other, and a horse on the towpath draws the whole train at a walking pace. Every boat is coupled to exactly one boat behind it by a short tow-rope, and the lead boat is coupled directly to the horse. The boats are numbered in the order they are coupled, from the lead boat to the last, and each carries a different consignment.\n\nAt Newbury lock the canal company's rules demand that the train be re-coupled in groups. The harbourmaster, a bluff man named Cornelius Hatch, has decreed that the boats shall be taken in consecutive groups of K, counting from the lead, and that within each complete group of K boats the order shall be exactly reversed: the boat which was K-th in the group becomes first, and the boat which was first becomes K-th. If the train has a number of boats that is not a multiple of K, then the boats in the final incomplete group, fewer than K in number, are to be left exactly as they are. The groups themselves stay in their original order, only the boats within each complete group change places.\n\nThe boats cannot be lifted out of the water and set down elsewhere; there is no wharf for that. Cornelius may only undo and re-tie the tow-ropes that join neighbouring boats, and he is determined to do this without ever setting aside more than a few boats' worth of ropes at one time. The numbers painted on the boats must not be changed, for each marks a consignment.\n\nThe lock-keeper's cottage is notable for a garden of improbably large marrows. A heron has taken to fishing from the lock gate. The company's accountant, a worried man, insists on counting the ropes twice.\n\nInput: line one gives N, the number of boats, and K. Line two gives the N painted numbers from lead boat to last. Output: the painted numbers after re-coupling, lead boat first.\n\nConstraints: N up to 10^6; K between 1 and N; numbers up to 10^9. Only the links between neighbours may be changed; extra memory must not grow with N.",
 "clues": ["coupled to exactly one boat behind it by a short tow-rope", "within each complete group of K boats the order shall be exactly reversed", "the boats in the final incomplete group, fewer than K in number, are to be left exactly as they are", "may only undo and re-tie the tow-ropes that join neighbouring boats"],
 "decoys": ["The lock-keeper's cottage is notable for a garden of improbably large marrows", "A heron has taken to fishing from the lock gate"],
 "core": "In a chain of linked items, reverse each complete block of K in place by rewiring links, leaving a short final block alone.",
 "gloss": [("narrowboat", "a long, thin canal boat", True), ("towpath", "a path beside a canal for towing animals", True), ("consignment", "a batch of goods sent together", True), ("harbourmaster", "an official in charge of a harbour", True), ("decreed", "ordered officially", True)],
 "why": {"ll-dummy": "A dummy head is useful here too, but it is a helper for removing or changing the first node; reversal in groups is the main idea.", "tp-ends": "Swapping two ends needs random access, which a chain does not have."},
 "alt": [],
 "tell": "Reverse blocks in a linked chain: re-tie each link to point backward within a block, then connect block to block."},

{"id": "sc-145", "v": "ll-dummy", "dom": "bead stringing", "diff": "M",
 "title": "The Flawed Beads of Master Okonkwo",
 "story": "Master Adebayo Okonkwo is the last stringer of ceremonial beads in the market quarter of Ilesha, and his craft is to thread hundreds of small glass beads on a single cord so that they hang in a long chain, each bead joined to the next bead along. The first bead on the chain is the one hung nearest the neck of the wearer; the last bead is the one that rests at the waist. Every bead carries a code number stamped into its base by the glassmaker, and beads of the same code can be found in many places along a chain.\n\nA shipment from a new glassmaker has been found to contain a flaw. Beads stamped with a certain code, X, have a hairline crack that makes them break if worn. Master Okonkwo must remove every bead with code X from the chain, wherever it lies, however many there are, and join together the beads on either side of each removed bead so that the chain remains a single unbroken chain in the original order of the remaining beads. The beads are far too delicate to be unthreaded and rethreaded on a new cord: the chain must be repaired where it stands, by cutting out the flawed beads and rejoining neighbours.\n\nThere is a particular difficulty that has caught out his apprentices before. If the very first bead of the chain happens to be flawed, there is no earlier bead to join to the next, and the position the wearer thinks of as 'the start of the chain' has to change. Likewise, several flawed beads may sit side by side, or the whole chain may turn out to be flawed. He has devised a way of handling the start of the chain just like any other place in the chain, rather than treating it as a special case with its own rules.\n\nThe market is famed for its dyed cottons and for a particularly pungent fish stew. The master's wife sells palm wine from a stall opposite. A travelling photographer has been pestering him to pose.\n\nInput: line one gives N and X. Line two gives the N code numbers from the neck end to the waist end. Output: the codes of the remaining beads in order, or the word EMPTY if none remain.\n\nConstraints: N up to 10^6; codes up to 10^9. Modify the chain in place; no new cord.",
 "clues": ["each bead joined to the next bead along", "must remove every bead with code X from the chain, wherever it lies", "the chain must be repaired where it stands", "If the very first bead of the chain happens to be flawed", "handling the start of the chain just like any other place in the chain"],
 "decoys": ["The master's wife sells palm wine from a stall opposite", "A travelling photographer has been pestering him to pose"],
 "core": "Delete every node with a given value from a linked chain, including possibly the first, without special-casing the start.",
 "gloss": [("ceremonial", "used for formal rituals", True), ("stringer", "a person who threads items onto a string", True), ("hairline", "very thin", True), ("pungent", "having a sharp smell", True), ("apprentices", "people learning a craft", True)],
 "why": {"ll-reverse": "No reversing is involved.", "ll-merge": "There is only one chain, so nothing is merged."},
 "alt": [],
 "tell": "Deleting from a linked chain where the first item may go: put a placeholder in front so the start behaves like any other link."},

{"id": "sc-146", "v": "ll-merge", "dom": "parades", "diff": "E",
 "title": "The Float Procession of Saint Crispin's Day",
 "story": "The town of Bellmouth holds a procession every year on Saint Crispin's Day, and this year two guilds have each prepared a train of decorated floats: the Cordwainers' Guild and the Drapers' Guild. Each train is a line of floats, each float being tied by a tow-rope to the float behind it, and the lead float of the train is tied to the tractor at the front. The floats of each train have been arranged by their heights, from the shortest at the head to the tallest at the tail, because the old town gate has a low arch and a tall float at the front would topple the ones behind it as it squeezed through.\n\nThe mayor has decreed that the two trains must process as ONE train through the gate, with the floats of both guilds interleaved in order of height, shortest first, so that the tall floats pass the gate last. The floats are heavy and delicate, and the parade marshal, a bustling woman named Georgiana Pike, refuses to have them detached from their wheels and lifted onto other chassis, nor has the town the money to build a third set of tow-ropes. She will only allow the existing tow-ropes between floats to be untied and re-tied to different floats, so that every float of both guilds finishes up in one single train, each float tied to the next-taller one, with ties between floats of the same height settled in favour of the Cordwainers, who march first by ancient custom.\n\nThe Cordwainers' float this year depicts a giant boot, and the Drapers' float depicts a bolt of cloth unrolling. A band of pipers will lead the march, and a retired colonel has been appointed to throw sweets to the children. The weather forecast promises drizzle by the afternoon.\n\nInput: line one gives A and B, the number of floats in each guild's train. Line two gives A heights, in non-decreasing order, for the Cordwainers; line three gives B heights in non-decreasing order for the Drapers. Output: the heights of the combined train from head to tail.\n\nConstraints: A and B up to 10^6; heights up to 10^9. The existing floats and ropes are to be reused; no new floats may be created.",
 "clues": ["each float being tied by a tow-rope to the float behind it", "arranged by their heights, from the shortest at the head to the tallest at the tail", "only allow the existing tow-ropes between floats to be untied and re-tied", "ties between floats of the same height settled in favour of the Cordwainers"],
 "decoys": ["The Cordwainers' float this year depicts a giant boot", "a retired colonel has been appointed to throw sweets to the children"],
 "core": "Merge two sorted linked chains into one sorted chain by relinking the existing nodes, preferring the first on ties.",
 "gloss": [("cordwainers", "shoemakers", True), ("drapers", "cloth merchants", True), ("float", "a decorated vehicle in a parade", True), ("chassis", "the frame of a vehicle", True), ("interleaved", "mixed together in alternation", True)],
 "why": {"tp-merge": "That merges arrays by reading from two cursors into a new output; here existing linked items are relinked and no new output structure is created.", "ll-dummy": "A placeholder head helps, but the main idea is combining two ordered chains."},
 "alt": [],
 "tell": "Two sorted linked chains become one by relinking: repeatedly attach whichever front is smaller to the tail of the result."},

{"id": "sc-147", "v": "td-up", "dom": "cave systems", "diff": "H",
 "title": "The Longest Crawl in the Wookey Caverns",
 "story": "Beneath the Mendip Hills lies a cave system that the cavers of Wells have mapped over three generations. The system has a single entrance, and from it the tunnels branch, at every chamber, into at most two further tunnels leading to deeper chambers; no tunnels ever rejoin, so the whole system, drawn on paper, looks like an upside-down tree, with the entrance at the top. Every chamber is recorded by its identification number, and the length of each tunnel between two chambers is taken to be exactly one unit, because the cavers count the number of tunnels they must crawl through, not their lengths in metres.\n\nThe Cave Rescue Organisation has asked for the length of the longest crawl that exists in the cave. A crawl is a route from some chamber to some other chamber that passes through each tunnel at most once, and it need not pass through the entrance: it may start in a deep chamber, climb up to a junction, and go down again into a different branch. The length of the crawl is the number of tunnels in it. The Organisation is not interested in which chambers are the endpoints, only in the length of the longest route that can be found anywhere in the system. They have noted that the longest route may or may not pass through the entrance, and that the system is huge, so a method that starts a fresh journey from every chamber and explores everything reachable is bound to repeat enormous amounts of work.\n\nThe Organisation holds a pub quiz every Friday at the Hunters' Lodge. A mascot hedgehog is stuffed and mounted in the clubhouse. A visiting professor of geology has been unwise enough to criticise the maps.\n\nInput: line one gives N, the number of chambers, numbered 1 to N, with chamber 1 the entrance. The next N lines each give two numbers: the left and right child tunnels' chambers of chamber i, with 0 meaning none. Output: the number of tunnels in the longest crawl.\n\nConstraints: N up to 10^6; the structure is a binary tree rooted at chamber 1. Each chamber should be examined a constant number of times in all.",
 "clues": ["branch, at every chamber, into at most two further tunnels", "no tunnels ever rejoin", "it need not pass through the entrance: it may start in a deep chamber, climb up to a junction, and go down again into a different branch", "starts a fresh journey from every chamber and explores everything reachable is bound to repeat enormous amounts of work"],
 "decoys": ["The Organisation holds a pub quiz every Friday at the Hunters' Lodge", "A mascot hedgehog is stuffed and mounted in the clubhouse"],
 "core": "The longest path between any two nodes of a binary tree; each node can combine the depths reported by its two children.",
 "gloss": [("cavers", "people who explore caves", True), ("chamber", "a cave room", True), ("crawl", "a low tunnel route", True), ("generations", "periods of about thirty years", True), ("system", "a connected set of things", True)],
 "why": {"td-down": "Passing context down the branches does not help; the answer at each junction is made from what its two branches report upward.", "gr-bfs": "Exploring from a start does not apply, since the route has no fixed start."},
 "alt": [],
 "tell": "Each junction combines the best depths from its two branches, then reports a single depth upward; track the best combination seen."},

{"id": "sc-148", "v": "td-down", "dom": "river deltas", "diff": "M",
 "title": "The Toll Stations of the Indus Delta",
 "story": "In the delta of a great river, the water divides and divides again as it nears the sea, until it reaches the coast through a score of channels. The boatmen of the delta pay tolls at stations placed at each fork of the channels, and the Delta Authority has recorded, for every station, a toll in rupees that a boat must pay to pass through it. A boat enters at the head of the delta, at the first station, and from every station it can continue into at most two lower channels, a left channel or a right channel, each leading to a further station; once a boat has entered a channel, it never returns to the station it left, and the channels never merge again. A boat that reaches a station with no lower channels, being a station on the coast, goes out to sea; the journey ends there.\n\nThe Authority's accountant, Ravindra Menon, wishes to know how many of the possible journeys from the head of the delta to the sea cost exactly a given total toll, T. Each journey is a route from the first station to a coastal station, and the cost of the journey is the sum of the tolls at all the stations it passes through, including the first and the coastal one. Two journeys are different if they end at different coastal stations. Ravindra has the delta recorded as a map of stations with each station's left and right neighbours.\n\nThe delta is famous for its mangroves, which shelter a variety of crabs, and for a species of freshwater dolphin that is said to be blind. A local festival involves floating thousands of tiny lamps on the water. Ravindra's tea is, on the day in question, unusually weak.\n\nThe key to his method must be that a boat's cost so far is known as it arrives at a station; the cost has to be carried from the head of the delta to each station along the way, so that when the boat reaches the coast the total is ready to compare with T. The toll at one station does not change according to the stations beyond it.\n\nInput: line one gives N and T. The next N lines each give a station's toll and its left and right neighbours (0 meaning none). Station 1 is the head. Output: the number of coast-bound journeys costing exactly T.\n\nConstraints: N up to 10^6; tolls between -1000 and 1000; T between -10^9 and 10^9.",
 "clues": ["continue into at most two lower channels", "the sum of the tolls at all the stations it passes through, including the first and the coastal one", "the cost has to be carried from the head of the delta to each station along the way", "never returns to the station it left, and the channels never merge again"],
 "decoys": ["The delta is famous for its mangroves, which shelter a variety of crabs", "A local festival involves floating thousands of tiny lamps on the water"],
 "core": "Count root-to-leaf paths in a binary tree whose node values add to exactly T, by carrying the running total downward.",
 "gloss": [("delta", "where a river splits before reaching the sea", True), ("tolls", "fees for passing", True), ("rupees", "the currency of several Asian countries", True), ("mangroves", "trees growing in salty coastal water", True), ("coastal", "at the coast", True)],
 "why": {"td-up": "Reporting values upward is the opposite direction; the question needs context from the root as you go down.", "ps-count": "Running totals of a list are similar, but the structure branches, so each route has its own."},
 "alt": [],
 "tell": "A running total that starts at the top and is handed down to each child, checked at the leaves."},

{"id": "sc-149", "v": "td-bst", "dom": "numismatics", "diff": "M",
 "title": "The Coin Cabinet of Sir Reginald Fane",
 "story": "Sir Reginald Fane, a Georgian collector of coins, arranged his cabinet in a novel manner. Instead of keeping his coins in trays by country, he kept them in a branching arrangement of little drawers. Each drawer holds exactly one coin, identified by the year in which it was minted, and each drawer has at most two drawers hanging below it, one to the left and one to the right. Sir Reginald's rule of arrangement, which his butler memorised, is this: for any drawer, every coin in the subtree of drawers hanging to its left was minted in an earlier year than the coin in the drawer itself, and every coin hanging to its right was minted in a later year. All years in the cabinet are different.\n\nThe cabinet has passed into the care of the Fitzwilliam Museum, whose keeper of coins, Dr Philippa Ormerod, wishes to answer the question, asked by many visitors: 'which is the K-th earliest coin in the cabinet?' That is, if all the years of all the coins were written in a list from earliest to latest, which year stands in position K? Dr Ormerod has the cabinet recorded as a tree of drawers, with each drawer's left and right neighbours, and the recorded years. She does not wish to write out all the years and sort them, since Sir Reginald's arrangement, as she is perfectly aware, already has the order built into it. She would also prefer to stop looking the moment she has found the K-th, rather than examine every drawer in the cabinet, and to use memory proportional to the height of the arrangement, no more.\n\nSir Reginald, it is recorded, kept a pet monkey that once stole a Roman denarius and was found asleep with it in a hat. The museum's tea room serves a lemon cake of local renown. Dr Ormerod's cat is called Constantine.\n\nInput: line one gives N and K. The next N lines each give a drawer's year and its left and right neighbours (0 meaning none). Drawer 1 is the top. Output: the year of the K-th earliest coin.\n\nConstraints: N up to 10^6; K between 1 and N; years between 1 and 3000. It is guaranteed that Sir Reginald's rule of arrangement holds throughout.",
 "clues": ["every coin in the subtree of drawers hanging to its left was minted in an earlier year than the coin in the drawer itself, and every coin hanging to its right was minted in a later year", "the K-th earliest coin", "the order built into it", "stop looking the moment she has found the K-th"],
 "decoys": ["kept a pet monkey that once stole a Roman denarius", "The museum's tea room serves a lemon cake of local renown"],
 "core": "In a binary search tree, find the K-th smallest value; reading the tree in sorted order gives it directly.",
 "gloss": [("cabinet", "a piece of furniture with drawers", True), ("minted", "made by stamping metal", True), ("denarius", "a silver coin of ancient Rome", True), ("subtree", "a node together with everything below it", True), ("novel", "new and unusual", True)],
 "why": {"td-up": "Combining children's answers would also work but ignores the order the arrangement already gives.", "hp-topk": "Selecting the K-th by a heap over the values ignores that they are already arranged in order."},
 "alt": [],
 "tell": "A tree where left is smaller and right is larger: visiting left, self, right produces the values in order, so stop at the K-th."},

{"id": "sc-150", "v": "td-lca", "dom": "chivalric orders", "diff": "M",
 "title": "The Common Superior of the Order of Saint Agnes",
 "story": "The Order of Saint Agnes is a chivalric order founded in the twelfth century, and its structure is strictly hierarchical. At its summit stands the Grand Master, who has no superior in the Order. Every other knight reports to exactly one knight above him, his commander, and no knight has more than two knights reporting directly to him, for the founder, a mathematician as well as a crusader, believed that no one could properly supervise more than two. In this way the Order forms a tree, with the Grand Master at its root; there are no loops, and every knight has a chain of command that leads upward, commander by commander, to the Grand Master.\n\nWhen two knights are involved in a dispute, the Order's statutes require that it be settled by the nearest superior whom they both have in their chains of command: the knight who lies in the chain of command of both and who stands lowest in the hierarchy, so that the dispute goes no higher than necessary. A knight is considered to be in his own chain of command, so that if one disputant is the commander, direct or indirect, of the other, then the commander himself settles the matter. The Chancellor of the Order, Sir Evelyn Thorne, receives many such disputes and is tired of hunting through the rolls.\n\nThe Order's chapel has a famous stained-glass window depicting a pelican. The knights are required to wear a grey cloak on feast days, a requirement that they resent in summer. The Order owns a small vineyard whose wine is said to be only just drinkable.\n\nSir Evelyn has the Order recorded as a tree: for each knight, his number, and the numbers of the knights reporting directly to him, left and right. Knights are numbered from 1 to N, and every knight has a different number. He receives Q disputes, each naming two knights who are certain to be in the Order.\n\nInput: line one gives N and Q. The next N lines each give the left and right subordinates of knight i (0 meaning none); knight 1 is the Grand Master. The next Q lines each give two knight numbers. Output: for each dispute, the number of the knight who settles it.\n\nConstraints: N up to 10^5; Q up to 10^5. Moving upward from each disputant, one step at a time, will be far too slow if the Order is a long, thin line of commanders.",
 "clues": ["the nearest superior whom they both have in their chains of command", "A knight is considered to be in his own chain of command", "the knight who lies in the chain of command of both and who stands lowest in the hierarchy", "there are no loops"],
 "decoys": ["The Order's chapel has a famous stained-glass window depicting a pelican", "The Order owns a small vineyard whose wine is said to be only just drinkable"],
 "core": "For two nodes of a tree, find the deepest node that is an ancestor of both (a node counts as its own ancestor).",
 "gloss": [("chivalric", "relating to the code and customs of knights", True), ("hierarchical", "arranged in ranks", True), ("statutes", "formal written rules", True), ("subordinate", "someone of lower rank", True), ("chancellor", "a senior official", True)],
 "why": {"td-up": "Reporting values upward is the mechanism, but the question is specifically for the lowest node above two given ones.", "gr-bfs": "No fewest-moves question is asked."},
 "alt": [],
 "tell": "The lowest shared ancestor of two nodes: look for the first node where the two chains of command meet."},

{"id": "sc-151", "v": "tb-levels", "dom": "mycology", "diff": "E",
 "title": "The Mycelium Survey at Lathbury Wood",
 "story": "Lathbury Wood is a very old oak wood, and under its floor a mycologist named Dr Wilhelmina Sauer has mapped a network of fungal threads, a mycelium, which she believes to be many centuries old. The network begins at a single point, the mother node, and from every node there branch out at most two further threads, each leading to a daughter node; no thread ever rejoins another, so the whole network is, on the page, a tree with the mother node at the top. Dr Sauer has measured the nutrient concentration at every node, a whole number in micrograms per gram of soil.\n\nA botanist visiting from Prague has asked a question that sounds simple. He wants the AVERAGE nutrient concentration at each depth below the mother node. The mother node is at depth zero by itself, the daughter nodes immediately below it are at depth one, their daughters at depth two, and so on, each depth being a whole layer of the network, with every node of that depth, from the far left to the far right. For each depth, he wants the total concentration of all the nodes at that depth divided by the number of nodes at that depth. The botanist does not want an overall average, nor an average along any one thread; he wants one figure per layer, from the topmost layer to the bottommost.\n\nThe wood is a nature reserve and visitors are asked to keep to the paths. Dr Sauer's research assistant, a student called Bartholomew, has a phobia of slugs, which is a drawback in his chosen field. The local ranger has an alarming moustache.\n\nThe obvious way to produce the answer is to take the network one layer at a time, finishing every node of one depth before starting on the nodes of the next depth, and to note, as each layer is completed, how many nodes it had.\n\nInput: line one gives N, the number of nodes, numbered 1 to N, node 1 being the mother node. The next N lines give, for node i, its concentration and the numbers of its left and right daughters (0 meaning none). Output: the average concentration of each depth, from depth zero downward, one per line, to one decimal place.\n\nConstraints: N up to 10^6; concentrations up to 10^6.",
 "clues": ["the AVERAGE nutrient concentration at each depth below the mother node", "one figure per layer, from the topmost layer to the bottommost", "finishing every node of one depth before starting on the nodes of the next depth"],
 "decoys": ["has a phobia of slugs, which is a drawback in his chosen field", "The local ranger has an alarming moustache"],
 "core": "For each level of a binary tree, compute something over all nodes at that level (here the average), level by level from the top.",
 "gloss": [("mycologist", "a scientist who studies fungi", True), ("mycelium", "the thread-like body of a fungus", True), ("nutrient", "a substance that nourishes", True), ("daughter node", "a node directly below another", True), ("layer", "one level of a structure", False)],
 "why": {"td-down": "Carrying a value down a single path does not give a figure over a whole layer.", "gr-bfs": "A shortest-route question is not asked."},
 "alt": [],
 "tell": "One answer per depth: process the tree a full layer at a time, noting the layer's size as you go."},

{"id": "sc-152", "v": "tr-basic", "dom": "street directories", "diff": "M",
 "title": "The Street Index of the Almanac of Brevoort",
 "story": "The Almanac of Brevoort is the city's annual directory, and its editor, a magisterial gentleman called Cornelius Vandermeer, is preparing a new section: an index of street names for the use of cab drivers and postmen. The city has a hundred thousand streets, and the names have been supplied by the council in no particular order, with a great deal of overlap in their beginnings: dozens of streets begin with 'Saint', hundreds with 'New', and scores begin with 'King', 'Queen', 'Market', and 'Upper'.\n\nThe index must answer three kinds of request. First, a clerk may ADD a new street name, as the council approves new building estates. Second, a postman may ask whether a certain name is a complete street name, in full, that exists in the index. Third, and most commonly, a cab driver may ask whether ANY street in the index starts with a given sequence of letters, because he remembers only that the street he wants begins with 'Wil' or 'Pem' and is trying to jog his memory. The answer to the third kind need not list the streets; yes or no will do. All three kinds of request arrive one after another, in any order, and must each be answered at once, as the almanac's compositors work at speed.\n\nCornelius has pointed out that if each request were answered by looking through the entire list of street names from the beginning, the process would take the cab drivers so long that they would give up and ask a policeman instead. He wants the cost of each request to depend only on the length of the name or beginning being asked about, and not on the number of streets in the index. The names share their beginnings, and he would like the index to take advantage of this, storing each shared beginning only once.\n\nThe almanac's cover is bound in a green cloth that fades horribly in sunlight. The printing works has a clock tower that is always seven minutes slow. Cornelius is rumoured to compose limericks in his spare time.\n\nInput: line one gives Q, the number of requests. Each of the next Q lines gives a type (1, 2 or 3) and a lowercase string. Output: for each request of type 2 or 3, YES or NO.\n\nConstraints: Q up to 5 * 10^5; total length of all strings up to 5 * 10^6.",
 "clues": ["whether ANY street in the index starts with a given sequence of letters", "the cost of each request to depend only on the length of the name or beginning being asked about", "storing each shared beginning only once", "must each be answered at once"],
 "decoys": ["The almanac's cover is bound in a green cloth that fades horribly in sunlight", "The printing works has a clock tower that is always seven minutes slow"],
 "core": "Support adding words and asking whether a word exists or whether any word starts with a given prefix, in time depending only on the string length.",
 "gloss": [("magisterial", "having an air of authority", True), ("directory", "a list of names and addresses", True), ("compositors", "people who set type for printing", True), ("overlap", "shared beginnings", False), ("jog", "to refresh", True)],
 "why": {"hs-seen": "A set can tell whether a whole name exists but cannot answer 'does anything start with these letters' without scanning.", "tr-search": "No board or grid is being searched."},
 "alt": [],
 "tell": "Insert, find a whole word, and find any word with this beginning: letters stored as a tree where words share their beginnings."},
]
